import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Metronic 9 (Tailwind 4 + KTUI) presentation assets for the v2 theme, served from the panel's own origin:
 * the compiled stylesheet (design tokens, `kt-*` components and the utility classes the theme markup names) and the
 * Keenicons icon font (filled style). `styles.css` is generated by `scripts/build-metronic-css.mjs`
 * from a licensed Metronic package; it is committed so the server keeps running without a build step.
 * Every file is read once and addressed by its content hash, so a changed file gets a new immutable URL.
 */
// A plain path, not a URL object: under a DOM test environment the global URL class is not the one node:fs accepts.
const HERE = dirname(fileURLToPath(import.meta.url))
const read = (file: string): Buffer => readFileSync(join(HERE, 'metronic', file))
const sha256 = (bytes: string | Uint8Array): string => createHash('sha256').update(bytes).digest('hex')

const FONTS = Object.freeze([
  { family: 'keenicons-filled', file: 'keenicons-filled.woff' },
] as const)

type MetronicAsset = { body: string | Uint8Array<ArrayBuffer>; contentType: string }
const files = new Map<string, MetronicAsset>()
const versioned = (path: string, body: string | Uint8Array): string => `${path}?v=${sha256(body).slice(0, 16)}`

const fontBodies = FONTS.map(font => ({ ...font, path: `/assets/metronic/${font.file}`, body: new Uint8Array(read(font.file)) }))
for (const font of fontBodies) files.set(font.path, { body: font.body, contentType: 'font/woff' })

// Inter (the Metronic typeface) for Latin text, unmodified variable files from @fontsource-variable/inter 5.2.8
// (SIL Open Font License 1.1, vendor/inter/LICENSE). The unicode ranges keep it to Latin: Arabic text always takes
// IBM Plex Sans Arabic. A file that does not match its pinned SHA-256 fails the import instead of serving other bytes.
const INTER = Object.freeze([
  { file: 'inter-latin-wght-normal.woff2', sha256: '3100e775e8616cd2611beecfa23a4263d7037586789b43f035236a2e6fbd4c62',
    range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD' },
  { file: 'inter-latin-ext-wght-normal.woff2', sha256: '34b9c504cab7a73e37b746343a449132e56cf7b5481af2cb81dc74dcff25c956',
    range: 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF' },
] as const)
const INTER_CSS = INTER.map(face => {
  const body = new Uint8Array(readFileSync(join(HERE, 'inter', face.file)))
  if (sha256(body) !== face.sha256) throw new Error(`vendored ${face.file} does not match its pinned SHA-256`)
  const path = `/assets/metronic/${face.file}`
  files.set(path, { body, contentType: 'font/woff2' })
  return `@font-face{font-family:'Inter';font-style:normal;font-weight:100 900;font-display:swap;src:url(${versioned(path, body)}) format('woff2');unicode-range:${face.range}}`
}).join('\n')

const ICONS_PATH = '/assets/metronic/keenicons.css'
const ICONS_CSS = INTER_CSS + '\n' + fontBodies.map(font => `@font-face{font-family:'${font.family}';font-style:normal;font-weight:normal;font-display:block;src:url(${versioned(font.path, font.body)}) format('woff')}`).join('\n')
  // The icon rules join the `components` layer (same layer order as styles.css, which is linked after this file), so
  // a v2 rule can still hide or reposition an icon while utilities keep the last word.
  + '\n@layer properties,theme,base,v2,components,utilities;\n@layer components{\n' + read('keenicons.css').toString('utf8') + '}\n'
files.set(ICONS_PATH, { body: ICONS_CSS, contentType: 'text/css; charset=utf-8' })

const STYLES_PATH = '/assets/metronic/styles.css'
const STYLES_CSS = read('styles.css').toString('utf8')
files.set(STYLES_PATH, { body: STYLES_CSS, contentType: 'text/css; charset=utf-8' })

/** The Metronic stylesheet; it must be linked before the v2 theme stylesheets because it declares the layer order. */
export const METRONIC_STYLESHEET_HREF = versioned(STYLES_PATH, STYLES_CSS)
export const METRONIC_ICONS_STYLESHEET_HREF = versioned(ICONS_PATH, ICONS_CSS)

/** Every path this module serves. */
export const METRONIC_ASSET_PATHS: readonly string[] = Object.freeze([...files.keys()])

export const metronicAsset = (path: string): MetronicAsset | undefined => files.get(path)
